/* MODULE kh11 · Bước 2 Hiểu khách hàng · STP: ghép phân khúc, chọn tệp và định vị thành một chuỗi
   8 bài × 7 câu. Ghép kh01 (phân khúc), kh02 (chọn tệp), tp01 (định vị) thành một chuỗi; không dạy lại từng phần.
   Mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kh11', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kh11-01', skill:'insight', read:'6 phút', t:'Viết slogan trước rồi mới tìm khách — vì sao chuỗi này hay gãy?',
  situation:'Một thương hiệu bánh mì que đóng gói từ Hải Phòng vào TP.HCM. Đội đã có slogan "giòn tan cho cả nhà", đã chụp bộ ảnh gia đình, in 20.000 tờ rơi hết 10 triệu đồng phát ở khu dân cư. Tháng đầu bán chậm. Đọc ghi chú đơn mới thấy: phần lớn đơn là dân văn phòng mua hộp 10 cái để ăn sáng — nhóm chưa từng được nhắc trong thông điệp.',
  concept:{ name:'STP: phân khúc → chọn tệp → định vị',
    body:'STP gồm ba bước theo đúng thứ tự. <b>Segmentation</b> (phân khúc): chia thị trường thành các nhóm có nhu cầu khác nhau. <b>Targeting</b> (chọn thị trường mục tiêu): chọn nhóm mình sẽ phục vụ. <b>Positioning</b> (định vị): quyết định mình đứng ở đâu trong đầu nhóm đó, so với lựa chọn họ đang dùng. Ý tưởng phân khúc được Wendell Smith nêu năm 1956; Kotler & Keller (Marketing Management) đặt ba bước thành khung chuẩn của chiến lược marketing. Thứ tự quan trọng vì bước sau lấy đầu vào từ bước trước: chưa chia thì không có gì để chọn; chưa chọn ai thì không biết định vị trong đầu ai. Module này không dạy lại từng phần (kh01, kh02, tp01) mà nối chúng thành một chuỗi.' },
  example:'Làm lại theo thứ tự. S: đọc 400 đơn đầu, chia theo dịp mua — ăn sáng văn phòng khoảng 55%, ăn vặt gia đình 30%, quà biếu 15%. T: chọn ăn sáng văn phòng vì đông nhất và chưa đối thủ nào làm hộp cho văn phòng. P: "bữa sáng 5 phút cho dân văn phòng, giòn tới trưa". Lúc này mới thấy slogan "cho cả nhà" là định vị cho một nhóm chưa hề được chọn. Tờ rơi cũng phát sai chỗ: chỉ khoảng 25% người cầm tờ rơi là dân văn phòng.',
  takeaway:'Chia trước, chọn sau, định vị cuối: câu định vị chỉ đúng khi biết nó nói với nhóm nào.',
  apply:'Cho dữ liệu một tiệm trà sữa: học sinh tan trường (45% đơn), dân văn phòng đặt app buổi chiều (35%), khách đặt tiệc sinh nhật (20%). Viết ba dòng S, T, P cho tiệm, mỗi dòng không quá 25 chữ. Đạt khi: (1) dòng T chọn đúng một nhóm và nêu một lý do; (2) dòng P nhắc lại đúng nhóm ở dòng T; (3) không dòng nào dùng chữ "mọi người".',
  mistakes:['Viết slogan và chụp ảnh trước, rồi mới hỏi khách là ai.','Coi STP là ba bài tập rời, mỗi phần một người làm và không ai đối chiếu với nhau.'],
  q:[
  { type:'mcq', stem:'Đoán trước: lỗi gốc của thương hiệu bánh mì que nằm ở đâu?',
    options:[{k:'a',t:'Tờ rơi in quá ít, 20.000 tờ chưa đủ phủ hết khu dân cư'},{k:'b',t:'Định vị và làm thông điệp trước khi chia và chọn khách'},
             {k:'c',t:'Bánh chưa đủ ngon nên khách gia đình không mua lại lần hai'},{k:'d',t:'Giá bán còn cao hơn bánh mì que của đối thủ trong thành phố'}],
    answer:'b', why:{a:'In thêm tờ rơi cho sai nhóm chỉ nhân lên cái sai; vấn đề không nằm ở số lượng.',
      b:'Đúng. Slogan "cho cả nhà" ra đời trước khi biết ai đang mua; chuỗi đi ngược chiều.',
      c:'Không có dữ kiện về vị bánh; dữ kiện cho thấy người mua thật là một nhóm khác.',
      d:'Không có dữ kiện về giá; dân văn phòng vẫn mua đều ở mức giá hiện tại.'} },
  { type:'mcq', stem:'Tháng sau còn 30 triệu cho marketing. Bạn chọn làm gì trước?',
    options:[{k:'a',t:'In thêm 40.000 tờ rơi "giòn tan cho cả nhà" phát rộng ra các quận'},{k:'b',t:'Chụp lại bộ ảnh gia đình đẹp hơn, chạy quảng cáo cho người 30–45 tuổi'},
             {k:'c',t:'Chốt nhóm ăn sáng văn phòng, viết lại định vị rồi mới làm ấn phẩm'},{k:'d',t:'Chia đều ngân sách cho cả ba nhóm khách để không bỏ sót ai cả'}],
    answer:'c', why:{a:'Phát rộng hơn một thông điệp nói sai nhóm là tốn thêm tiền cho cùng một lỗi.',
      b:'Ảnh đẹp hơn vẫn nói với nhóm chưa được chọn; nhắm theo tuổi cũng không trúng dịp ăn sáng.',
      c:'Đúng. Đi lại đúng thứ tự S → T → P, rồi ấn phẩm mới có cái để bám vào.',
      d:'Chia đều 30 triệu cho ba nhóm thì nhóm nào cũng quá mỏng để nhớ tới mình.'} },
  { type:'calc', stem:'Tiệm in 20.000 tờ rơi hết 10 triệu đồng; khoảng 25% người nhận là dân văn phòng. Chi phí cho mỗi tờ rơi đến đúng người văn phòng là bao nhiêu đồng?',
    unit:'đ', ans:2000, tol:1, wrong:[[500,'SAI_MAU_SO'],[125,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Số tờ đến đúng nhóm = 20.000 × 25% = 5.000 tờ.','Chi phí mỗi tờ trúng nhóm = 10.000.000 ÷ 5.000 = <b>2.000đ</b> — gấp 4 lần con số 500đ/tờ tính trên tổng số tờ.'] },
  { type:'mcq', stem:'Vì sao bước chọn tệp (T) phải đứng trước bước định vị (P)?',
    options:[{k:'a',t:'Định vị là chỗ đứng trong đầu một nhóm cụ thể; chưa chọn nhóm thì chưa biết so với ai'},{k:'b',t:'Vì giáo trình quy định thứ tự này, làm khác đi sẽ bị chấm là sai quy trình'},
             {k:'c',t:'Vì định vị tốn tiền hơn nên phải để sau cùng, khi đã có đủ ngân sách'},{k:'d',t:'Vì chọn tệp dùng được dữ liệu nội bộ, còn định vị phải thuê nghiên cứu ngoài'}],
    answer:'a', why:{a:'Đúng. Cùng một sản phẩm, so với lựa chọn của dân văn phòng và của gia đình sẽ ra hai chỗ đứng khác nhau.',
      b:'Thứ tự có lý do logic, không phải luật hình thức; hiểu lý do mới áp dụng được.',
      c:'Định vị có thể làm rất rẻ; nó đứng sau vì cần đầu vào, không vì chi phí.',
      d:'Cả hai bước đều có thể dùng dữ liệu nội bộ và phỏng vấn khách.'} },
  { type:'mcq', stem:'Tình huống mới: một app học tiếng Anh viết khẩu hiệu "học dễ, học vui cho mọi lứa tuổi" rồi mới phân tích người dùng. Điều gì dễ xảy ra nhất?',
    options:[{k:'a',t:'Thông điệp rộng nên app sẽ thu hút nhiều người dùng hơn các app ngách'},{k:'b',t:'Không sao, vì thông điệp vẫn giữ nguyên được dù sau này chọn tệp nào'},
             {k:'c',t:'Người dùng sẽ tự chia thành nhóm, app không cần làm thêm gì nữa'},{k:'d',t:'Câu "mọi lứa tuổi" không nói nhóm nào cần gì nên khó khiến ai đổi app'}],
    answer:'d', why:{a:'Thông điệp rộng thường bị bỏ qua vì không ai thấy nó nói về mình (xem lại B:kh02-02).',
      b:'Nếu sau đó chọn "người đi làm cần thi IELTS", câu "học vui cho mọi lứa tuổi" sẽ nói sai điều họ cần.',
      c:'Người dùng tự tụ lại không có nghĩa sản phẩm và thông điệp đã phục vụ họ.',
      d:'Đúng. Người đang dùng app khác cần một lý do riêng để đổi; câu chung không cho lý do đó.'} },
  { type:'mcq', stem:'Theo bài viết của Smith (1956), phân khúc khác "khác biệt hoá sản phẩm" ở điểm nào?',
    options:[{k:'a',t:'Phân khúc chỉnh sản phẩm theo nhu cầu từng nhóm; khác biệt hoá kéo thị trường về phía sản phẩm mình'},{k:'b',t:'Phân khúc dành cho doanh nghiệp nhỏ, còn khác biệt hoá dành cho doanh nghiệp lớn có nhiều vốn'},
             {k:'c',t:'Phân khúc chia khách theo tuổi, còn khác biệt hoá chia khách theo thu nhập hằng tháng của họ'},{k:'d',t:'Hai cách thực chất là một, Smith chỉ đặt hai cái tên khác nhau cho cùng một ý tưởng'}],
    answer:'a', why:{a:'Đúng. Smith xem đây là hai chiến lược thay thế: thích ứng theo cầu, hay cố uốn cầu theo cung.',
      b:'Smith không chia theo quy mô doanh nghiệp; cả hai cách đều dùng được ở mọi cỡ công ty.',
      c:'Phân khúc không đồng nghĩa với chia theo tuổi; còn khác biệt hoá không phải là cách chia khách.',
      d:'Smith viết bài chính là để tách hai chiến lược này ra.'} },
  { type:'mcq', stem:'Đồng nghiệp nói: "Mình có câu định vị hay rồi, giờ tìm phân khúc nào hợp với câu đó." Điểm yếu trong lập luận này là gì?',
    options:[{k:'a',t:'Không yếu: câu định vị hay sẽ tự hút đúng nhóm khách cần đến'},{k:'b',t:'Câu định vị phải chờ giám đốc duyệt nên chưa được làm ở bước này'},
             {k:'c',t:'Đi ngược chiều: chọn khách cho hợp câu chữ, thay vì câu chữ phục vụ khách đã chọn'},{k:'d',t:'Phân khúc chỉ làm được khi có ngân sách nghiên cứu thị trường thật lớn'}],
    answer:'c', why:{a:'Câu hay mà sai người thì vẫn sai; bánh mì que là ví dụ.',
      b:'Ai duyệt không phải vấn đề; vấn đề là thứ tự lập luận.',
      c:'Đúng. Cách làm này có thể chọn một nhóm nhỏ hay khó thắng chỉ vì nó hợp câu chữ.',
      d:'Đọc lại đơn hàng, đếm hoá đơn theo dịp đã là phân khúc; không cần ngân sách lớn.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kh11-02', skill:'insight', read:'6 phút', t:'Phòng gym chia hội viên theo tuổi hay theo cách họ tập?',
  situation:'Một chuỗi phòng gym ở Đà Nẵng có 800 hội viên, đang chia theo tuổi: 18–24, 25–34, 35 trở lên. Tỉ lệ gia hạn ba nhóm gần như nhau, khoảng 44–48%. Một quản lý thử chia lại theo cách tập: 300 người tập đều từ 3 buổi/tuần gia hạn 70%; 500 người tập thất thường chỉ gia hạn 30% (số minh hoạ). Chủ chuỗi hỏi: nên chăm nhóm nào, bằng cách nào?',
  concept:{ name:'Bốn cơ sở phân khúc',
    body:'Kotler & Keller nêu bốn cơ sở chia thị trường tiêu dùng. <b>Địa lý</b>: tỉnh, quận, thành thị hay nông thôn, khí hậu. <b>Nhân khẩu học</b>: tuổi, giới, thu nhập, nghề, giai đoạn gia đình. <b>Tâm lý</b>: lối sống, giá trị, tính cách. <b>Hành vi</b>: dịp mua, lợi ích tìm kiếm, mức dùng, mức trung thành. Ba cơ sở đầu mô tả <i>người đó là ai</i>; hành vi và nhu cầu mô tả <i>họ mua, dùng thế nào và vì sao</i> — nên thường chia ra các nhóm cần cách làm khác nhau. Địa lý và nhân khẩu học vẫn có ích ở bước tìm người: nhắm quảng cáo, đặt điểm bán. Phân khúc không đồng nghĩa với nhóm tuổi; nhóm tuổi chỉ là phân khúc khi chính tuổi tạo ra nhu cầu khác (xem lại B:kh01-01 và B:kh01-03).' },
  example:'Theo tuổi, tỉ lệ gia hạn chênh nhau chưa tới 4 điểm phần trăm — không gợi ra việc gì khác nhau cho ba nhóm. Theo hành vi, chênh 40 điểm: 70% nhóm thất thường không gia hạn, so với 30% ở nhóm tập đều. Việc cần làm lộ ra ngay. Nhóm thất thường: nhắn tin khi vắng 10 ngày, gợi ý lịch 2 buổi cố định mỗi tuần. Nhóm tập đều: ưu đãi gia hạn sớm gói 12 tháng. Tuổi lúc này chỉ còn dùng để chọn giờ mở lớp và kênh nhắn tin.',
  takeaway:'Chia theo cách khách mua và dùng trước; dùng tuổi, nơi ở để tìm họ sau.',
  apply:'Cho bảng của một shop sữa hạt (số minh hoạ): theo tuổi, tỉ lệ mua lại nhóm 18–30 là 38%, nhóm 31–45 là 41%; theo lý do mua, nhóm "thay sữa bò vì không dung nạp" là 72%, nhóm "uống thử vì tò mò" là 12%. Viết ba câu: cách chia nào dùng được, chênh bao nhiêu điểm phần trăm, mỗi nhóm cần một việc gì khác. Đạt khi: (1) chọn chia theo lý do mua và nêu đúng 60 điểm %; (2) hai việc làm khác nhau thật; (3) tuổi chỉ xuất hiện ở vai trò tìm khách.',
  mistakes:['Dừng ở nhóm tuổi vì dễ lọc trong báo cáo, dù các nhóm cư xử y như nhau.','Chia theo tâm lý bằng tính từ đẹp ("năng động", "hiện đại") không gắn với hành vi nào đo được.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với số liệu phòng gym, cách chia nào gợi ra nhiều việc cần làm khác nhau nhất?',
    options:[{k:'a',t:'Theo tuổi, vì nhóm 25–34 đông nhất và có thu nhập ổn định nhất'},{k:'b',t:'Theo quận nơi ở, vì người ở gần phòng tập thường đến đều hơn'},
             {k:'c',t:'Theo giới tính, vì nam và nữ thường chọn bài tập khác nhau'},{k:'d',t:'Theo tần suất tập, vì tỉ lệ gia hạn hai nhóm chênh nhau rất xa'}],
    answer:'d', why:{a:'Ba nhóm tuổi gia hạn gần như nhau; chia theo tuổi không đổi được quyết định nào.',
      b:'Có thể đúng, nhưng chưa có dữ liệu quận; còn dữ liệu tần suất thì đã cho chênh lệch rõ.',
      c:'Khác bài tập không có nghĩa khác khả năng gia hạn; chưa có dữ liệu ủng hộ.',
      d:'Đúng. Chênh 40 điểm % giữa hai nhóm hành vi nghĩa là mỗi nhóm cần một cách giữ chân khác.'} },
  { type:'mcq', stem:'Ngân sách giữ chân có hạn. Bạn ưu tiên làm gì cho nhóm 500 người tập thất thường?',
    options:[{k:'a',t:'Nhắn tin khi họ vắng 10 ngày và gợi ý lịch hai buổi cố định mỗi tuần'},{k:'b',t:'Giảm 20% phí gia hạn cho cả 800 hội viên để giữ chân tất cả cùng lúc'},
             {k:'c',t:'Chạy quảng cáo nhắm người 25–34 tuổi để thay chỗ người sắp rời đi'},{k:'d',t:'Mở thêm lớp yoga buổi tối vì nhóm trên 35 tuổi thích lớp nhẹ nhàng'}],
    answer:'a', why:{a:'Đúng. Nhóm này rời đi vì không giữ được thói quen; việc cần làm là giúp họ quay lại phòng tập.',
      b:'Giảm cho cả nhóm tập đều — vốn đã gia hạn 70% — là tặng tiền cho người đằng nào cũng ở lại.',
      c:'Kéo người mới mà không sửa lý do rời đi thì người mới cũng rời theo cùng một cách.',
      d:'Tuổi không phải biến giải thích chuyện gia hạn trong dữ liệu này.'} },
  { type:'calc', stem:'Nhóm tập đều gia hạn 70%, nhóm tập thất thường gia hạn 30%. Hai nhóm chênh nhau bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:40, tol:0.1, wrong:[[133.3,'NHAM_DIEM_PHAN_TRAM'],[57.1,'NHAM_DIEM_PHAN_TRAM']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Chênh lệch điểm phần trăm = 70% − 30% = <b>40 điểm %</b>.','Đừng nhầm với chênh lệch tương đối: (70 − 30) ÷ 30 ≈ 133%. Theo tuổi, chênh chỉ khoảng 4 điểm %.'] },
  { type:'mcq', stem:'Một shop thời trang mô tả: "khách của chúng tôi năng động, yêu tự do". Đây là cơ sở phân khúc nào, và vấn đề là gì?',
    options:[{k:'a',t:'Nhân khẩu học; vấn đề là còn thiếu thông tin thu nhập của khách'},{k:'b',t:'Tâm lý; nhưng chưa gắn với hành vi nào đo được hay nhắm được'},
             {k:'c',t:'Hành vi; vì "yêu tự do" cho biết khách hay đi du lịch xa'},{k:'d',t:'Địa lý; vì người yêu tự do thường sống ở các thành phố lớn'}],
    answer:'b', why:{a:'"Năng động", "yêu tự do" là lối sống, không phải tuổi hay thu nhập.',
      b:'Đúng. Tâm lý có ích khi nối được với việc khách làm: mua gì, dịp nào, ở đâu.',
      c:'Đó là suy diễn; mô tả không nói gì về việc khách đã làm.',
      d:'Không có căn cứ nối lối sống này với nơi ở.'} },
  { type:'mcq', stem:'Khi nào chia theo địa lý là cách chia chính đúng?',
    options:[{k:'a',t:'Khi doanh nghiệp mới có một cửa hàng và chưa biết gì về khách'},{k:'b',t:'Khi đối thủ lớn đã chia theo vùng miền và đang làm có hiệu quả'},
             {k:'c',t:'Khi nơi ở làm nhu cầu khác thật, như máy sưởi ở miền Bắc và miền Nam'},{k:'d',t:'Khi thương hiệu muốn quảng cáo rẻ hơn bằng cách nhắm hẹp theo từng tỉnh thành'}],
    answer:'c', why:{a:'Chưa biết khách thì đi hỏi và đọc đơn; chia theo nơi ở không thay được hiểu biết đó.',
      b:'Chép cách chia của đối thủ không chứng minh cách đó hợp với mình.',
      c:'Đúng. Khi khí hậu hay vùng miền tạo ra nhu cầu khác, chia theo địa lý chính là chia theo nhu cầu.',
      d:'Nhắm hẹp theo tỉnh là chuyện tiếp cận, không phải lý do chọn cách chia.'} },
  { type:'mcq', stem:'Tình huống mới: hãng nước giặt chia "người giặt máy cửa trước" và "người giặt tay ở nhà trọ". Cách chia này thuộc cơ sở nào, và vì sao dùng được?',
    options:[{k:'a',t:'Nhân khẩu học, vì người ở trọ thường trẻ và có thu nhập thấp hơn'},{k:'b',t:'Địa lý, vì nhà trọ tập trung ở vài quận gần các khu công nghiệp'},
             {k:'c',t:'Tâm lý, vì giặt tay thể hiện một lối sống tiết kiệm và cẩn thận'},{k:'d',t:'Hành vi sử dụng, vì cách giặt đòi công thức và bao bì khác nhau'}],
    answer:'d', why:{a:'Tuổi và thu nhập có thể đi kèm, nhưng thứ quyết định sản phẩm là cách giặt.',
      b:'Nơi ở giúp tìm người, nhưng bản thân cách chia dựa trên việc họ giặt thế nào.',
      c:'Giặt tay thường do điều kiện (không có máy), không phải tính cách.',
      d:'Đúng. Giặt máy cửa trước cần ít bọt; giặt tay cần dịu da tay, gói nhỏ — hai sản phẩm khác nhau.'} },
  { type:'mcq', stem:'Hai đề xuất: A chia theo tuổi (nhắm quảng cáo được ngay), B chia theo tần suất tập (phải nối dữ liệu quẹt thẻ). Lập luận nào cân nhắc đúng đánh đổi?',
    options:[{k:'a',t:'Chọn A, vì nhắm được quảng cáo ngay là ưu tiên số một của phòng gym lúc này'},{k:'b',t:'Chọn B làm cách chia, rồi dùng tuổi để chọn giờ lớp và kênh nhắn tin'},
             {k:'c',t:'Chọn A, vì dữ liệu quẹt thẻ có thể sai nên không đáng để tin cậy'},{k:'d',t:'Không chọn cách nào, vì phòng gym cỡ nhỏ thì chưa cần phân khúc'}],
    answer:'b', why:{a:'Nhắm được nhanh một nhóm không khác gì nhau thì cũng không đổi được kết quả gia hạn.',
      b:'Đúng. Mỗi cơ sở làm một việc: hành vi để quyết định làm gì, nhân khẩu học để tìm và nói với họ.',
      c:'Dữ liệu quẹt thẻ là hành vi thật, thường đáng tin hơn tuổi khai lúc đăng ký.',
      d:'800 hội viên với hai nhóm gia hạn chênh 40 điểm là đủ lý do để chia.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kh11-03', skill:'measure', read:'7 phút', t:'Ba phân khúc trên giấy — cái nào thật sự dùng được?',
  situation:'Một xưởng gốm Bát Tràng bán online cân nhắc ba phân khúc (số minh hoạ). A: quán cà phê mới mở cần bộ cốc đồng bộ, khoảng 1.500 quán/năm ở Hà Nội và TP.HCM, lãi gộp 4 triệu đồng mỗi quán. B: "người yêu nét đẹp truyền thống", chưa ai biết bao nhiêu. C: người sưu tầm men lam, khoảng 200 người, lãi gộp 1 triệu/người/năm. Làm một dòng riêng cho mỗi phân khúc tốn khoảng 300 triệu đồng/năm.',
  concept:{ name:'Năm tiêu chí của một phân khúc dùng được',
    body:'Kotler & Keller nêu năm tiêu chí. <b>Đo lường được</b>: ước được quy mô và sức mua. <b>Đủ lớn</b>: đủ lãi để bù chi phí làm riêng. <b>Tiếp cận được</b>: có kênh để với tới. <b>Khác biệt</b>: phản ứng khác nhóm khác với cùng một chương trình. <b>Hành động được</b>: doanh nghiệp đủ người, tiền và năng lực để làm một chương trình riêng cho nhóm đó. B:kh01-05 đã dạy bốn phép thử đầu; tiêu chí thứ năm quay sang hỏi chính mình — nhóm có thật mà mình không đủ sức phục vụ thì cũng chưa dùng được. Năm tiêu chí là cửa lọc ở cuối bước S: trượt một tiêu chí thì chưa cần mang sang bước T để chấm độ hấp dẫn.' },
  example:'Chấm từng phân khúc. A: đo được (đếm quán mới đăng ký kinh doanh), đủ lớn (1.500 × 4 triệu = 6 tỉ lãi gộp tiềm năng; giành 10% là 600 triệu, hơn 300 triệu chi phí), tiếp cận được (nhóm chủ quán, nhà thiết kế nội thất), khác biệt (đặt số lượng, in logo), hành động được (xưởng đã có lò lớn). B: trượt ở đo lường và tiếp cận. C: đo được, khác biệt rõ, nhưng lãi tối đa 200 × 1 triệu = 200 triệu, chưa bù nổi 300 triệu — trượt "đủ lớn". Chỉ A qua đủ năm cửa.',
  takeaway:'Năm tiêu chí là cửa lọc trước khi chấm điểm hấp dẫn: trượt một cửa thì chưa đáng tính tiếp.',
  apply:'Cho phân khúc D: "khách sạn 3 sao cần bát đĩa in logo", khoảng 400 khách sạn, lãi gộp 6 triệu/khách sạn/năm, ước giành 20%, chi phí làm dòng riêng 300 triệu/năm, liên hệ qua phòng mua hàng. Viết bảng 5 dòng (tiêu chí – đạt hay không – lý do một câu). Đạt khi: (1) tính lãi giành được = 480 triệu và so với 300 triệu; (2) mỗi dòng có lý do riêng, không chép lại nhau; (3) kết luận chọn hay loại có căn cứ.',
  mistakes:['Giữ phân khúc vì mô tả nghe hay, dù không đo hay với tới được.','Quên hỏi "mình có đủ sức phục vụ không" — chọn nhóm có thật nhưng ngoài năng lực.'],
  q:[
  { type:'mcq', stem:'Đoán trước: phân khúc nào qua được cả năm tiêu chí?',
    options:[{k:'a',t:'A — quán cà phê mới mở cần bộ cốc đồng bộ'},{k:'b',t:'B — người yêu nét đẹp truyền thống Việt Nam'},
             {k:'c',t:'C — người sưu tầm men lam, khách sành và trả cao'},{k:'d',t:'Chưa kết luận được khi chưa khảo sát cả ba nhóm'}],
    answer:'a', why:{a:'Đúng. A đếm được, đủ lãi để bù chi phí, có kênh với tới, nhu cầu khác và xưởng làm được.',
      b:'B không đếm được và không biết nói với họ ở đâu — trượt hai cửa.',
      c:'C rõ nét nhưng lãi tối đa 200 triệu, chưa bù được 300 triệu chi phí làm riêng.',
      d:'Dữ kiện đã đủ để loại B và C; khảo sát thêm chỉ cần để tinh chỉnh A.'} },
  { type:'mcq', stem:'Chủ xưởng thích phân khúc C vì "khách sành, trả giá cao". Bạn đề xuất gì?',
    options:[{k:'a',t:'Chọn C, vì khách sành sẽ truyền miệng giúp xưởng nổi tiếng thật nhanh trong giới'},{k:'b',t:'Chọn B, vì mô tả rộng nhất nên chắc sẽ có nhiều người mua nhất'},
             {k:'c',t:'Làm cả ba dòng cùng lúc, xem dòng nào bán tốt rồi tính tiếp sau'},{k:'d',t:'Chọn A làm dòng chính; phục vụ C bằng hàng sẵn có, không làm dòng riêng'}],
    answer:'d', why:{a:'Truyền miệng là hy vọng, chưa phải con số; dòng riêng cho C vẫn lỗ ít nhất 100 triệu.',
      b:'Rộng mà không đo, không với tới được thì không biết bắt đầu từ đâu.',
      c:'Ba dòng tốn 900 triệu/năm; hai dòng trượt tiêu chí sẽ ăn mất lãi của dòng tốt.',
      d:'Đúng. Vẫn bán cho C, nhưng không bỏ 300 triệu làm riêng cho một nhóm không đủ lớn.'} },
  { type:'calc', stem:'Phân khúc C: mỗi khách mua trung bình 2,5 triệu và để lại 1 triệu lãi gộp mỗi năm; làm dòng riêng tốn 300 triệu/năm. Cần ít nhất bao nhiêu khách để hoà vốn dòng riêng?',
    unit:'khách', ans:300, tol:1, wrong:[[120,'QUEN_CHI_PHI_BIEN_DOI']], errors:['QUEN_CHI_PHI_BIEN_DOI'],
    steps:['Số khách hoà vốn = chi phí làm riêng ÷ lãi gộp mỗi khách (không chia cho doanh thu 2,5 triệu).','300 triệu ÷ 1 triệu = <b>300 khách</b> — nhiều hơn cả 200 người của phân khúc, nên C trượt "đủ lớn" kể cả khi giành được hết.'] },
  { type:'mcq', stem:'Phân khúc B "người yêu nét đẹp truyền thống" trượt rõ nhất ở những tiêu chí nào?',
    options:[{k:'a',t:'Đủ lớn và hành động được, vì nhóm này quá nhỏ so với năng lực xưởng'},{k:'b',t:'Khác biệt, vì người yêu truyền thống mua giống hệt chủ quán cà phê'},
             {k:'c',t:'Đo lường và tiếp cận: không đếm được, không biết nói với họ ở đâu'},{k:'d',t:'Không trượt tiêu chí nào, cần một chiến dịch thật truyền cảm hứng'}],
    answer:'c', why:{a:'Chưa đếm được thì chưa thể nói nhóm này nhỏ hay lớn.',
      b:'Không có dữ kiện về cách họ mua; vấn đề nằm ở chỗ không đo và không tìm được họ.',
      c:'Đúng. Mô tả toàn là cảm xúc, không gắn với dữ liệu hay kênh nào (xem lại B:kh01-05).',
      d:'Chiến dịch hay không thay được việc biết họ là ai và ở đâu.'} },
  { type:'mcq', stem:'Tiêu chí "hành động được" khác bốn tiêu chí còn lại ở điểm nào?',
    options:[{k:'a',t:'Nó đo quy mô phân khúc bằng doanh thu thay vì bằng số người'},{k:'b',t:'Nó xét năng lực của chính doanh nghiệp, không xét đặc điểm nhóm khách'},
             {k:'c',t:'Nó chỉ áp dụng cho doanh nghiệp B2B bán hàng cho khách tổ chức'},{k:'d',t:'Nó là tiêu chí phụ, có thể bỏ qua khi bốn tiêu chí kia đều đạt'}],
    answer:'b', why:{a:'Đo quy mô thuộc tiêu chí "đo lường được" và "đủ lớn".',
      b:'Đúng. Bốn tiêu chí đầu nhìn ra thị trường; tiêu chí này nhìn vào trong: mình có làm nổi không.',
      c:'Áp dụng cho mọi loại hình; quán nhỏ cũng phải hỏi mình có đủ người phục vụ không.',
      d:'Nhóm hấp dẫn mà mình không phục vụ nổi thì chọn vào chỉ làm hỏng lời hứa.'} },
  { type:'mcq', stem:'Tình huống mới: một nhà sách thấy nhóm "phụ huynh mua sách luyện thi lớp 10" đo được, đủ lớn, khác biệt, có nhóm Facebook để tiếp cận — nhưng nhà sách không có ai tư vấn chọn sách. Kết luận hợp lý?',
    options:[{k:'a',t:'Chọn ngay, vì đạt bốn trên năm tiêu chí là tỉ lệ đủ cao rồi'},{k:'b',t:'Loại hẳn, vì đã trượt một tiêu chí thì phân khúc đó coi như bỏ đi'},
             {k:'c',t:'Chưa hành động được; cân nhắc tuyển hay đào tạo người tư vấn trước'},{k:'d',t:'Đổi sang nhóm học sinh tự mua sách vì nhóm này dễ phục vụ hơn'}],
    answer:'c', why:{a:'Tiêu chí là cửa lọc, không phải điểm cộng; thiếu năng lực tư vấn thì phụ huynh sẽ thất vọng.',
      b:'"Hành động được" có thể sửa bằng đầu tư; trượt hôm nay không có nghĩa là trượt mãi.',
      c:'Đúng. Phân khúc tốt; việc cần làm là xây năng lực trước khi nhận lời phục vụ.',
      d:'Đổi nhóm chỉ vì dễ phục vụ là bỏ một phân khúc đã qua bốn cửa mà chưa tính lãi.'} },
  { type:'mcq', stem:'Một bạn trình bày: "Phân khúc C có 200 khách, mỗi khách trả 2,5 triệu, vậy là 500 triệu, đủ bù 300 triệu chi phí." Sai ở đâu?',
    options:[{k:'a',t:'Lấy doanh thu so với chi phí; dùng lãi gộp 1 triệu/khách thì tối đa chỉ 200 triệu'},{k:'b',t:'Nhân sai: 200 khách × 2,5 triệu phải ra 5 tỉ chứ không phải 500 triệu đồng'},
             {k:'c',t:'Không sai; doanh thu lớn hơn chi phí nghĩa là dòng riêng này có lãi'},{k:'d',t:'Sai vì phải tính cho 5 năm thì mới thấy giá trị thật của nhóm khách này'}],
    answer:'a', why:{a:'Đúng. Chi phí làm riêng phải được bù bằng lãi gộp, không phải doanh thu; và đó là khi giành được 100% nhóm.',
      b:'200 × 2,5 triệu = 500 triệu là phép nhân đúng; cái sai nằm ở chỗ dùng doanh thu.',
      c:'Doanh thu chưa trừ giá vốn; 1,5 triệu mỗi khách đã đi vào đất, men, lò.',
      d:'Chi phí 300 triệu cũng lặp lại mỗi năm; kéo dài thời gian không đổi được kết luận.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kh11-04', skill:'brand', read:'7 phút', t:'Nhắm một nhóm, vài nhóm hay cả thị trường — và có ai nói nên nhắm rộng?',
  situation:'Một thương hiệu nước mắm nhỏ ở Phú Quốc có lãi gộp 520 triệu/năm khi chỉ bán cho nhà hàng hải sản. Đội bán hàng muốn làm thêm hai dòng cho "bếp gia đình" và "quà du lịch", ước tổng lãi gộp ba dòng là 800 triệu. Mỗi dòng cần 130 triệu/năm chi phí riêng cho bao bì, kênh và nhân sự (số minh hoạ). Cùng lúc, một cố vấn nói: "đừng chia nhỏ, hãy với tới thật nhiều người mua nước mắm".',
  concept:{ name:'Bốn cách chọn thị trường mục tiêu',
    body:'Theo Kotler & Armstrong (Principles of Marketing) có bốn mức. <b>Đại trà</b>: một chương trình cho cả thị trường, bỏ qua khác biệt. <b>Phân hoá</b>: nhiều phân khúc, mỗi phân khúc một chương trình. <b>Tập trung</b>: dồn sức vào một hay vài ngách. <b>Vi mô</b>: làm theo từng khu vực hay từng người. Càng hẹp càng sắc nhưng càng phụ thuộc một nhóm; càng rộng càng nhiều doanh thu tiềm năng nhưng tốn chi phí hơn và dễ nhạt. Có một quan điểm khác: Byron Sharp (How Brands Grow, 2010, Viện Ehrenberg-Bass) cho rằng thương hiệu lớn lên chủ yếu nhờ với tới thật nhiều người mua của cả ngành hàng, nên nên nhắm rộng hơn và bớt chia nhỏ. Đây là một tranh luận còn mở giữa hai trường phái, không phải luật.' },
  example:'Tính lãi sau chi phí riêng. Tập trung: 520 − 130 = 390 triệu. Phân hoá ba dòng: 800 − 3 × 130 = 410 triệu. Phân hoá chỉ hơn 20 triệu nhưng phải quản ba bao bì, ba kênh. Nếu con số 800 triệu bị ước cao 10% (thực tế 720), phân hoá còn 330 triệu — thua tập trung. Góc nhìn của Sharp gợi một lối thứ ba: giữ một sản phẩm nhưng đưa lên kệ siêu thị để nhiều người mua nước mắm thấy và mua được — mở rộng độ phủ mà không tách dòng. Không phương án nào đúng sẵn; nó tuỳ giả định nào chắc hơn.',
  takeaway:'Rộng hay hẹp là đánh đổi giữa độ sắc và độ phủ — tính lãi sau chi phí riêng trước khi chọn.',
  apply:'Cho một tiệm bánh có hai phương án: (1) tập trung vào bánh sinh nhật văn phòng, lãi gộp 300 triệu, chi phí riêng 80 triệu; (2) phân hoá thêm bánh cưới và bánh ăn vặt, tổng lãi gộp 450 triệu, mỗi dòng chi phí riêng 80 triệu. Tính lãi sau chi phí riêng của hai phương án và viết ba câu khuyến nghị. Đạt khi: (1) ra 220 triệu và 210 triệu; (2) nêu một rủi ro của phương án được chọn; (3) nói rõ giả định nào cần kiểm thêm.',
  mistakes:['Chọn phân hoá vì tổng lãi gộp lớn hơn, quên nhân chi phí riêng theo số dòng.','Trình bày "nhắm rộng" hay "nhắm hẹp" như chân lý duy nhất, không nói đó là một tranh luận.'],
  q:[
  { type:'mcq', stem:'Đoán trước: sau khi trừ chi phí riêng, phương án ba dòng hơn phương án một dòng bao nhiêu?',
    options:[{k:'a',t:'Hơn khoảng 280 triệu, vì tổng lãi gộp tăng từ 520 lên 800'},{k:'b',t:'Thua khoảng 130 triệu, vì phải gánh thêm chi phí hai dòng mới'},
             {k:'c',t:'Chỉ hơn khoảng 20 triệu, gần như hoà sau khi trừ chi phí'},{k:'d',t:'Hơn khoảng gấp đôi, vì có thêm hai nhóm khách mới chưa từng mua'}],
    answer:'c', why:{a:'280 triệu là chênh lệch lãi gộp, chưa trừ 260 triệu chi phí của hai dòng mới.',
      b:'Trừ chi phí rồi phân hoá vẫn nhỉnh hơn một chút: 410 so với 390 triệu.',
      c:'Đúng. 410 − 390 = 20 triệu — một khoảng rất mỏng so với độ phức tạp tăng thêm.',
      d:'Thêm nhóm khách không nhân đôi lãi khi mỗi nhóm kéo theo chi phí riêng.'} },
  { type:'mcq', stem:'Chủ thương hiệu hỏi năm nay nên chọn cách nào. Bạn đề xuất gì?',
    options:[{k:'a',t:'Phân hoá ngay ba dòng, vì tổng lãi gộp cao hơn tập trung'},{k:'b',t:'Giữ tập trung, thử nhỏ dòng bếp gia đình để kiểm ước tính'},
             {k:'c',t:'Chuyển hẳn sang đại trà, bán một chai giống nhau ở các kênh'},{k:'d',t:'Làm vi mô, mỗi nhà hàng một công thức nước mắm riêng biệt'}],
    answer:'b', why:{a:'Lãi gộp cao hơn nhưng lãi sau chi phí chỉ hơn 20 triệu; ước cao 10% là đổi chiều.',
      b:'Đúng. Khoảng cách quá mỏng để cược cả năm; thử nhỏ để biết con số 800 triệu có thật không.',
      c:'Bỏ hẳn nhóm nhà hàng đang mang lãi để làm đại trà là một bước nhảy chưa có dữ liệu.',
      d:'Vi mô đẩy chi phí làm riêng lên theo số nhà hàng; không hợp với một thương hiệu nhỏ.'} },
  { type:'calc', stem:'Phương án phân hoá: tổng lãi gộp 800 triệu/năm, ba dòng, mỗi dòng 130 triệu chi phí riêng. Lãi sau chi phí riêng là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:410, tol:0.5, wrong:[[670,'QUEN_CHI_PHI_CO_DINH'],[800,'QUEN_CHI_PHI_CO_DINH']], errors:['QUEN_CHI_PHI_CO_DINH'],
    steps:['Chi phí riêng = 3 dòng × 130 = 390 triệu.','Lãi sau chi phí riêng = 800 − 390 = <b>410 triệu</b>, chỉ hơn phương án tập trung (520 − 130 = 390) khoảng 20 triệu.'] },
  { type:'mcq', stem:'Quan điểm của Byron Sharp (2010) nên được trình bày thế nào trong bài này?',
    options:[{k:'a',t:'Là một trường phái có dữ liệu riêng, tranh luận với cách nhắm hẹp truyền thống'},{k:'b',t:'Là kết luận cả ngành đã chấp nhận, thay hẳn khung STP cũ trong các giáo trình'},
             {k:'c',t:'Là ý kiến cá nhân không dựa trên nghiên cứu, nên bỏ qua khi làm kế hoạch'},{k:'d',t:'Là cách làm chỉ dành cho hàng xa xỉ, không áp dụng cho hàng tiêu dùng nhanh'}],
    answer:'a', why:{a:'Đúng. Sharp dựa trên dữ liệu hành vi mua; nhiều người làm nghề phản biện. Người học cần biết cả hai phía.',
      b:'Giáo trình phổ biến vẫn dạy STP; đây là tranh luận, chưa phải thay thế.',
      c:'Quan điểm này dựa trên nhiều nghiên cứu dữ liệu mua hàng của Viện Ehrenberg-Bass.',
      d:'Ngược lại, phần lớn dữ liệu của Sharp đến từ hàng tiêu dùng nhanh.'} },
  { type:'mcq', stem:'Tình huống mới: một thương hiệu mỹ phẩm nhỏ chỉ có 200 triệu ngân sách năm đầu. Cách chọn thị trường nào hợp lý nhất để bắt đầu?',
    options:[{k:'a',t:'Đại trà, quảng cáo cho phụ nữ 18–50 tuổi trên toàn quốc'},{k:'b',t:'Tập trung vào một nhóm có nỗi đau rõ, như da dầu mụn tuổi đi làm'},
             {k:'c',t:'Phân hoá năm dòng cho năm loại da để không bỏ sót khách'},{k:'d',t:'Vi mô, nhắn tin cá nhân hoá cho từng người theo dữ liệu mua'}],
    answer:'b', why:{a:'200 triệu rải cho cả nước thì mỗi người thấy quá ít lần để nhớ.',
      b:'Đúng. Ngân sách nhỏ cần một bãi đổ bộ có thể thắng rõ (xem lại B:kh02-03).',
      c:'Năm dòng là năm lần chi phí riêng; ngân sách không đủ nuôi.',
      d:'Thương hiệu mới chưa có dữ liệu mua để cá nhân hoá.'} },
  { type:'mcq', stem:'Rủi ro lớn nhất của chiến lược tập trung là gì?',
    options:[{k:'a',t:'Thông điệp quá sắc khiến chính nhóm đã chọn thấy bị làm phiền'},{k:'b',t:'Chi phí cho mỗi khách thường cao hơn đại trà nên dễ lỗ ngay trong năm đầu'},
             {k:'c',t:'Không đo được kết quả vì nhóm khách quá nhỏ để có số liệu'},{k:'d',t:'Phụ thuộc một nhóm; nhóm đó co lại hay đối thủ lớn vào là chao đảo'}],
    answer:'d', why:{a:'Thông điệp sắc là điểm mạnh của tập trung, không phải rủi ro chính.',
      b:'Tập trung thường giảm chi phí mỗi khách vì nói trúng và xuất hiện đủ dày.',
      c:'Nhóm nhỏ vẫn đo được; nhiều khi còn dễ đo hơn.',
      d:'Đúng. Đặt hết trứng vào một giỏ: nhà hàng hải sản giảm khách là nước mắm giảm theo.'} },
  { type:'mcq', stem:'Hai ý kiến trong phòng họp: A "chia nhỏ để nói trúng từng nhóm", B "phủ rộng để nhiều người mua ngành hàng nhớ tới mình". Cách xử lý nào hợp lý?',
    options:[{k:'a',t:'Theo A, vì giáo trình STP đã chứng minh nhắm hẹp hiệu quả hơn nhắm rộng'},{k:'b',t:'Theo B, vì nghiên cứu Ehrenberg-Bass cho thấy phân khúc là việc vô ích'},
             {k:'c',t:'Bỏ cả hai, làm theo trực giác của chủ doanh nghiệp vì họ hiểu khách nhất'},{k:'d',t:'Ghi rõ giả định mỗi bên, thử nhỏ và so lãi sau chi phí trước khi chốt'}],
    answer:'d', why:{a:'STP là khung tư duy, không phải phép chứng minh rằng hẹp luôn tốt hơn rộng.',
      b:'Sharp không nói phân khúc vô ích; ông cảnh báo việc nhắm quá hẹp và bỏ qua người mua nhẹ.',
      c:'Trực giác có giá trị nhưng không thay được một phép thử rẻ.',
      d:'Đúng. Khi hai trường phái cùng có lý, dữ liệu của chính mình là trọng tài.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kh11-05', skill:'measure', read:'7 phút', t:'Phân khúc to nhất có phải phân khúc đáng chọn nhất?',
  situation:'Một app đặt lịch spa ở TP.HCM cân nhắc ba phân khúc (số minh hoạ). A: dân văn phòng muốn gội đầu dưỡng sinh buổi trưa — 50.000 người, ước giành 4%, lãi gộp 300.000đ/khách/năm. B: mẹ sau sinh cần massage tại nhà — 12.000 người, ước giành 15% vì chưa ai làm kỹ, lãi gộp 450.000đ. C: khách du lịch — 80.000 người, chỉ giành 1% vì phải cạnh tranh với khách sạn, lãi gộp 500.000đ. Cả đội nghiêng về C vì "to nhất".',
  concept:{ name:'Hấp dẫn = quy mô × khả năng thắng × biên lãi',
    body:'Kotler & Keller đánh giá phân khúc theo ba nhóm: quy mô và tăng trưởng; độ hấp dẫn về cấu trúc (đối thủ, sức ép giá); và mục tiêu, nguồn lực của doanh nghiệp. Một cách gom thành một con số: <b>lãi kỳ vọng = số khách trong phân khúc × tỉ lệ mình có thể giành × lãi gộp mỗi khách</b>. Khác bảng chấm điểm cộng ở B:kh02-01, phép nhân phạt nặng điểm yếu: một thừa số gần 0 kéo cả tích về gần 0, dù hai thừa số kia rất to. Tỉ lệ giành được là giả định yếu nhất — nó gói cả sức đối thủ lẫn lý do khách chọn mình — nên cần ghi nguồn và thử thay số.' },
  example:'A: 50.000 × 4% × 300.000đ = 600 triệu. B: 12.000 × 15% × 450.000đ = 810 triệu. C: 80.000 × 1% × 500.000đ = 400 triệu. C to nhất về số người nhưng đứng cuối về lãi. Thử độ nhạy: nếu B chỉ giành được 8% thay vì 15%, B còn 432 triệu — thua A. Vậy trước khi dồn tiền vào B, cần kiểm con số 15% bằng một đợt thử nhỏ với khoảng 200 mẹ sau sinh. B:kh02-06 dạy cách ước số khách; bài này ghép nó với khả năng thắng.',
  takeaway:'Nhân quy mô với khả năng thắng và biên lãi; phân khúc to mà khó thắng có thể đứng cuối.',
  apply:'Cho hai phân khúc của một tiệm giặt sấy: D — sinh viên ký túc xá, 6.000 người, giành 10%, lãi gộp 200.000đ/năm; E — homestay, 300 cơ sở, giành 20%, lãi gộp 5 triệu/năm. Tính lãi kỳ vọng mỗi phân khúc và viết hai câu chọn. Đạt khi: (1) ra 120 triệu và 300 triệu; (2) chỉ ra giả định yếu nhất; (3) tính được tỉ lệ giành tối thiểu để E vẫn hơn D (8%).',
  mistakes:['Chọn phân khúc to nhất mà không nhân với tỉ lệ có thể giành.','Cộng điểm các tiêu chí, để một điểm rất yếu bị điểm mạnh khác che mất.'],
  q:[
  { type:'mcq', stem:'Đoán trước: xếp theo lãi kỳ vọng, phân khúc nào đứng đầu?',
    options:[{k:'a',t:'C — khách du lịch, vì có tới 80.000 người'},{k:'b',t:'A — dân văn phòng, vì đông và dễ quảng cáo'},
             {k:'c',t:'Ba phân khúc ngang nhau vì biên lãi gần nhau'},{k:'d',t:'B — mẹ sau sinh, dù nhỏ nhất về số người'}],
    answer:'d', why:{a:'C to nhất nhưng chỉ giành được 1%, nên đứng cuối với 400 triệu.',
      b:'A đứng thứ hai với 600 triệu.',
      c:'Biên lãi gần nhau, nhưng tỉ lệ giành được chênh tới 15 lần.',
      d:'Đúng. B đạt 810 triệu nhờ tỉ lệ giành được cao và biên lãi khá.'} },
  { type:'mcq', stem:'Cả đội vẫn muốn chọn C. Bạn phản ứng thế nào?',
    options:[{k:'a',t:'Đưa phép nhân ba thừa số, chỉ ra 1% giành được kéo C xuống cuối'},{k:'b',t:'Đồng ý chọn C, vì phân khúc to cho dư địa tăng trưởng dài hạn'},
             {k:'c',t:'Chọn cả ba để không lỡ cơ hội, chia đều ngân sách cho mỗi nhóm'},{k:'d',t:'Đề nghị thuê báo cáo ngành du lịch trước khi bàn tiếp với cả đội'}],
    answer:'a', why:{a:'Đúng. Đặt ba con số cạnh nhau thì cuộc bàn chuyển từ "to nhất" sang "lãi nhất".',
      b:'Dư địa của C chỉ mở ra nếu giành được nhiều hơn 1%; hiện chưa có lý do để tin điều đó.',
      c:'Chia đều làm mỏng cả ba, kể cả B — nơi có cơ hội thắng rõ nhất.',
      d:'Báo cáo ngành cho số người, không trả lời được mình giành được bao nhiêu.'} },
  { type:'calc', stem:'Phân khúc B có 12.000 người, app giành được 15%, lãi gộp 450.000đ/khách/năm. Lãi kỳ vọng mỗi năm là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:810, tol:0.5, wrong:[[5400,'QUEN_TI_LE_CHUYEN_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Số khách giành được = 12.000 × 15% = 1.800 khách.','Lãi kỳ vọng = 1.800 × 450.000đ = 810.000.000đ = <b>810 triệu</b>. Quên tỉ lệ 15% sẽ ra 5.400 triệu — tức là giả định giành được cả phân khúc.'] },
  { type:'mcq', stem:'Vì sao phép nhân hợp hơn phép cộng điểm khi đánh giá độ hấp dẫn phân khúc?',
    options:[{k:'a',t:'Vì phép nhân cho ra con số lớn hơn, trông ấn tượng hơn khi trình bày'},{k:'b',t:'Vì một thừa số gần 0 làm cả phân khúc mất giá trị, phép cộng che điều đó'},
             {k:'c',t:'Vì phép cộng chỉ dùng được khi có đúng bốn tiêu chí như bài kh02'},{k:'d',t:'Vì phép nhân không cần giả định nào, còn phép cộng cần nhiều giả định'}],
    answer:'b', why:{a:'Độ lớn con số không phải lý do; cách hai phép tính xử lý điểm yếu mới là lý do.',
      b:'Đúng. Phân khúc 80.000 người mà gần như không thắng được thì vẫn gần như không có lãi.',
      c:'Phép cộng dùng được với bao nhiêu tiêu chí cũng được; vấn đề là nó bù trừ.',
      d:'Phép nhân cũng đầy giả định, nhất là tỉ lệ giành được.'} },
  { type:'mcq', stem:'Giả định nào trong bảng là yếu nhất và cần kiểm trước?',
    options:[{k:'a',t:'Số mẹ sau sinh ở TP.HCM, vì có thể tra từ thống kê số ca sinh hằng năm'},{k:'b',t:'Lãi gộp mỗi khách, vì app đã có bảng giá và chi phí của các đối tác'},
             {k:'c',t:'Tỉ lệ giành được 15%, vì nó gói cả sức đối thủ lẫn lý do khách chọn'},{k:'d',t:'Số khách du lịch, vì con số này thay đổi theo mùa trong năm'}],
    answer:'c', why:{a:'Số người tra được từ nguồn công khai, sai số nhỏ hơn.',
      b:'Lãi gộp đã có từ dữ liệu vận hành của chính app.',
      c:'Đúng. Đây là con số đoán nhiều nhất và làm thứ hạng đổi chiều khi thay đổi.',
      d:'Biến động mùa vụ có thật, nhưng C đã đứng cuối dù lấy số nào.'} },
  { type:'mcq', stem:'Nếu B chỉ giành được 8%, lãi kỳ vọng của B còn 432 triệu so với 600 triệu của A. Điều đó nói gì?',
    options:[{k:'a',t:'Thứ hạng đổi chiều; nên thử nhỏ để kiểm tỉ lệ giành trước khi chốt'},{k:'b',t:'B vẫn là lựa chọn số một vì nhóm mẹ sau sinh trung thành hơn'},
             {k:'c',t:'Phép tính vô nghĩa vì tỉ lệ giành được không ai biết trước'},{k:'d',t:'Nên chọn C, vì khi số liệu đều không chắc thì chọn nhóm to nhất cho an toàn'}],
    answer:'a', why:{a:'Đúng. Kết luận nhạy với một giả định thì đầu tư vào việc kiểm giả định đó trước.',
      b:'Mức trung thành chưa có trong dữ liệu; đó là thêm một giả định mới.',
      c:'Không biết chắc vẫn tính được kịch bản; phép thử độ nhạy chính là để làm việc đó.',
      d:'Chọn to nhất khi không chắc là quay lại đúng lỗi bài này cảnh báo.'} },
  { type:'mcq', stem:'Tình huống mới: chuỗi trà sữa so hai phân khúc. X: 100.000 người × 2% × 150.000đ. Y: 20.000 người × 12% × 120.000đ. Một bạn chọn X "vì gấp 5 lần số người". Nhận xét nào đúng?',
    options:[{k:'a',t:'Đúng, X gấp 5 lần số người nên lãi kỳ vọng cũng gấp khoảng 5 lần Y'},{k:'b',t:'Sai, Y thắng rõ vì tỉ lệ giành được 12% cao gấp sáu lần của X'},
             {k:'c',t:'X chỉ nhỉnh hơn Y (300 so với 288 triệu); cần xét thêm chi phí với tới'},{k:'d',t:'Không so được vì hai phân khúc có lãi gộp mỗi khách khác nhau'}],
    answer:'c', why:{a:'Số người gấp 5 nhưng tỉ lệ giành chỉ bằng 1/6, nên hai tích gần bằng nhau.',
      b:'Tỉ lệ cao không đủ; nhân hết ba thừa số thì X vẫn nhỉnh hơn một chút.',
      c:'Đúng. Kết luận của bạn kia tình cờ đúng chiều nhưng lý do sai; khoảng cách 12 triệu quá mỏng để quyết chỉ bằng con số này (xem lại B:kh02-07).',
      d:'Lãi gộp khác nhau chính là một thừa số trong phép nhân; vẫn so được.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kh11-06', skill:'brand', read:'7 phút', t:'Đã chọn tệp — viết câu định vị thế nào để không trôi khỏi tệp đó?',
  situation:'Một tiệm cơm văn phòng ở Hà Nội đã đi qua hai bước: chia theo dịp, rồi chọn tệp "nhân viên văn phòng đặt cơm trưa qua app, chỉ có 45 phút nghỉ". Đối thủ quanh đó đều hứa "ngon, rẻ". Tiệm muốn khác bằng "giao trong 30 phút". Tháng trước có 1.200 đơn, 1.020 đơn giao đúng hạn (số minh hoạ). Trưởng nhóm muốn in "luôn đúng 30 phút" lên túi đựng.',
  concept:{ name:'Câu định vị và ba tiêu chí của điểm khác biệt',
    body:'Câu định vị (xem lại B:tp01-01) có bốn vế: <b>cho ai</b> — lấy nguyên tệp đã chọn ở bước T; <b>thuộc ngành nào</b> — khung tham chiếu khách dùng để so; <b>khác gì</b> — điểm khác biệt; <b>vì sao tin</b> — bằng chứng. Kotler & Keller (dựa trên Keller) nêu ba nhóm tiêu chí để một điểm khác biệt đứng được: <b>khách thấy đáng muốn</b> (liên quan tới điều tệp đó cần, nghe khác và tin được); <b>mình làm được</b> (vận hành đủ sức giữ lời, nói ra được, giữ được lâu); và <b>khác đối thủ</b> (đối thủ chưa có hoặc khó bắt chước nhanh). Câu định vị là mắt xích nối T với P: đổi vế "cho ai" là đổi cả chuỗi.' },
  example:'Câu định vị: "Cho dân văn phòng chỉ có 45 phút nghỉ trưa, tiệm là cơm trưa giao tận bàn, giao trong 30 phút, vì bếp nấu theo khung giờ đặt trước và có 6 người giao riêng cho hai toà nhà." Chạy ba tiêu chí. Đáng muốn: có, vì giờ nghỉ ngắn. Khác đối thủ: có, đối thủ nói "ngon, rẻ". Làm được: mới đạt 85% (1.020 trên 1.200 đơn). In "luôn đúng 30 phút" khi 15% đơn còn trễ là hứa vượt vận hành (xem lại B:tp01-08). Nên sửa bếp trước, tạm hứa "trễ thì hoàn phí giao".',
  takeaway:'Vế "cho ai" lấy từ bước chọn tệp; điểm khác biệt phải đáng muốn, làm được và khác đối thủ.',
  apply:'Cho tiệm giặt ủi chọn tệp "người độc thân đi làm, không có thời gian cuối tuần". Đối thủ hứa "giặt sạch, giá rẻ". Tiệm có tủ nhận đồ 24/7 ở 3 chung cư; 92% đơn trả trong 24 giờ. Viết câu định vị bốn vế (không quá 45 chữ) và chấm ba tiêu chí. Đạt khi: (1) vế "cho ai" khớp nguyên tệp đã cho; (2) vế "vì sao tin" dùng số 92% hoặc tủ 24/7; (3) có một dòng nói tiêu chí nào còn yếu.',
  mistakes:['Viết vế "cho ai" khác tệp đã chọn, như "mọi người yêu ẩm thực".','Chọn điểm khác biệt khách thích nhưng vận hành chưa giữ được lời.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điểm khác biệt "giao trong 30 phút" đang yếu ở tiêu chí nào?',
    options:[{k:'a',t:'Đáng muốn, vì dân văn phòng không để ý tốc độ giao cơm'},{k:'b',t:'Làm được, vì mới 85% đơn giao đúng hạn'},
             {k:'c',t:'Khác đối thủ, vì các tiệm quanh đó đều đã hứa giao nhanh'},{k:'d',t:'Không yếu tiêu chí nào, có thể in lên túi ngay hôm nay'}],
    answer:'b', why:{a:'Với người chỉ có 45 phút nghỉ, tốc độ là điều họ cần nhất.',
      b:'Đúng. 15% đơn trễ nghĩa là cứ khoảng 7 đơn có 1 đơn phá lời hứa.',
      c:'Dữ kiện nói đối thủ hứa "ngon, rẻ", không phải giao nhanh.',
      d:'Hứa điều vận hành chưa giữ được sẽ làm khách thất vọng nhanh hơn.'} },
  { type:'mcq', stem:'Trưởng nhóm muốn in "luôn đúng 30 phút" lên túi. Bạn đề xuất gì?',
    options:[{k:'a',t:'In ngay, vì 85% là con số khá và khách sẽ không để ý 15% còn lại'},{k:'b',t:'Bỏ hẳn điểm khác biệt về tốc độ, quay về hứa "ngon, rẻ" như đối thủ'},
             {k:'c',t:'Sửa khâu bếp và giao trước, tạm hứa "trễ thì hoàn phí giao" đến khi đạt'},{k:'d',t:'Đổi tệp sang khách đặt cơm tối, vì nhóm này không vội như dân văn phòng'}],
    answer:'c', why:{a:'Người nhận đơn trễ chính là người đọc chữ "luôn" trên túi; vết lệch càng lộ.',
      b:'Bỏ điểm khác biệt đáng muốn và khác đối thủ chỉ vì chưa làm tròn là quá vội.',
      c:'Đúng. Giữ hướng định vị, kéo vận hành lên, và hứa điều đang làm được.',
      d:'Đổi tệp để né vấn đề vận hành là bẻ gãy cả chuỗi S → T đã chọn có lý do.'} },
  { type:'calc', stem:'Tháng trước tiệm có 1.200 đơn, trong đó 1.020 đơn giao đúng 30 phút. Tỉ lệ giao đúng hạn là bao nhiêu phần trăm?',
    unit:'%', ans:85, tol:0.1, wrong:[[15,'NHAM_TI_LE_ROI'],[117.6,'SAI_MAU_SO']], errors:['NHAM_TI_LE_ROI','SAI_MAU_SO'],
    steps:['Tỉ lệ đúng hạn = đơn đúng hạn ÷ tổng đơn.','1.020 ÷ 1.200 = 0,85 = <b>85%</b>. Phần còn lại, 15%, là tỉ lệ trễ.'] },
  { type:'mcq', stem:'Vế "cho ai" trong câu định vị nên lấy từ đâu?',
    options:[{k:'a',t:'Từ đúng tệp đã chọn ở bước T, ghi bằng nhu cầu hay dịp chứ không chỉ tuổi'},{k:'b',t:'Từ nhóm đông nhất trong báo cáo nhân khẩu học của fanpage tháng trước'},
             {k:'c',t:'Từ nhóm khách mà đội sáng tạo thấy dễ làm hình ảnh đẹp nhất'},{k:'d',t:'Từ nhóm khách mà đối thủ lớn nhất đang nói tới trong quảng cáo'}],
    answer:'a', why:{a:'Đúng. Đây là mắt xích T → P; ghi bằng nhu cầu ("chỉ có 45 phút nghỉ") giúp mọi người hiểu vì sao lời hứa quan trọng.',
      b:'Người theo dõi fanpage chưa chắc là tệp đã chọn (xem lại B:kh01-09).',
      c:'Chọn người theo độ dễ làm ảnh là để khâu sáng tạo quyết định chiến lược.',
      d:'Chép tệp của đối thủ là bỏ qua bước chọn tệp của chính mình.'} },
  { type:'mcq', stem:'Tình huống mới: hãng nước suối định khác biệt bằng "chai làm từ nhựa tái chế". Tệp đã chọn là người lao động mua lẻ ở tạp hoá, chọn theo giá và độ lạnh. Điểm khác biệt này trượt tiêu chí nào?',
    options:[{k:'a',t:'Làm được, vì nhựa tái chế khó mua được với số lượng lớn'},{k:'b',t:'Khác đối thủ, vì các hãng lớn đã dùng nhựa tái chế từ lâu'},
             {k:'c',t:'Vì sao tin, vì khách không tự kiểm được chai có tái chế không'},{k:'d',t:'Đáng muốn với tệp này, vì nó không chạm điều họ dùng để chọn'}],
    answer:'d', why:{a:'Có thể khó, nhưng dữ kiện không nói gì về nguồn cung.',
      b:'Dữ kiện không nói đối thủ đã làm; đó là giả định thêm.',
      c:'Bằng chứng có thể giải quyết bằng chứng nhận; vấn đề lớn hơn là tệp này không quan tâm.',
      d:'Đúng. Một điểm khác biệt tốt cho tệp khác vẫn vô dụng với tệp đã chọn.'} },
  { type:'mcq', stem:'Cho câu: "Cho những người yêu ẩm thực, chúng tôi là quán ăn ngon với nguyên liệu tươi." Lỗi lớn nhất là gì?',
    options:[{k:'a',t:'Câu quá ngắn, cần kể thêm lịch sử quán để tạo cảm xúc'},{k:'b',t:'Thiếu tên thương hiệu nên khách đọc xong không biết là của quán nào'},
             {k:'c',t:'Từ "ngon" quá phổ biến, nên thay bằng chữ "tuyệt hảo"'},{k:'d',t:'"Cho ai" không phải một tệp, "ngon, tươi" là điều ai cũng nói'}],
    answer:'d', why:{a:'Câu định vị là công cụ nội bộ; dài hơn không sửa được việc nó không chọn ai.',
      b:'Thêm tên không làm câu sắc hơn; thay tên đối thủ vào vẫn đúng.',
      c:'Đổi từ đẹp hơn vẫn là điểm tương đồng, không phải điểm khác biệt.',
      d:'Đúng. Câu này đứt ở cả T (không có tệp) lẫn P (không có điểm khác biệt).'} },
  { type:'mcq', stem:'Hai điểm khác biệt cho tiệm cơm: X "món theo chế độ ăn từng người" (khách rất thích, bếp chưa làm được), Y "giao 30 phút" (khách thích, bếp đạt 85%, đang sửa). Chọn cái nào lúc này hợp lý hơn?',
    options:[{k:'a',t:'X, vì khách thích nhất thì điểm khác biệt mạnh nhất, vận hành tính sau'},{k:'b',t:'Y, vì gần đạt cả ba tiêu chí; X cần năng lực bếp chưa hề có'},
             {k:'c',t:'Cả hai cùng lúc, để câu định vị có hai điểm khác biệt mạnh'},{k:'d',t:'Chưa chọn, chờ khảo sát thêm sáu tháng rồi mới quyết định'}],
    answer:'b', why:{a:'Đáng muốn mà không làm được thì thành lời hứa suông, hại hơn không hứa.',
      b:'Đúng. Đánh đổi ở đây là sức hút so với khả năng giữ lời; Y cân bằng hơn.',
      c:'Hai lời hứa cùng lúc làm câu định vị loãng và vận hành quá tải.',
      d:'Dữ kiện đã đủ để chọn; chờ sáu tháng là để đối thủ đi trước.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kh11-07', skill:'channel', read:'7 phút', t:'Định vị xong rồi — sản phẩm, giá, kênh và lời nói phải đổi gì theo?',
  situation:'Tiệm cơm văn phòng ở bài trước đã có định vị "cơm trưa giao trong 30 phút cho dân văn phòng chỉ có 45 phút nghỉ". Nhưng thực đơn vẫn có 40 món nấu theo yêu cầu, hộp cơm giá 50.000đ bán qua app tính hoa hồng 25%, và fanpage đăng ảnh mâm cơm gia đình cuối tuần. Giá vốn món ăn 18.000đ/hộp (số minh hoạ). Chủ tiệm hỏi: định vị đã đúng, sao khách chưa thấy gì khác?',
  concept:{ name:'Từ STP xuống 4P',
    body:'Định vị chỉ là lời hứa; khách cảm nhận nó qua bốn biến số marketing — 4P của McCarthy (1960): <b>sản phẩm</b>, <b>giá</b>, <b>phân phối</b> (kênh) và <b>truyền thông</b> (thông điệp). Mỗi P phải là hệ quả của STP. Sản phẩm làm được lời hứa cho tệp đã chọn. Giá hợp với cách tệp đó so sánh và vẫn để lại lãi sau chi phí kênh. Kênh đặt ở nơi tệp đó mua. Thông điệp nói đúng điểm khác biệt với đúng người. Cách kiểm nhanh: với mỗi P, hỏi "quyết định này phục vụ tệp nào, giữ lời hứa nào?". P nào trả lời bằng một nhóm khác là chỗ chuỗi đang rò.' },
  example:'Sản phẩm: 40 món nấu theo yêu cầu làm bếp chậm — cắt còn 8 món nấu sẵn theo khung 11h–12h để giữ lời 30 phút. Giá: 50.000đ qua app, trừ hoa hồng 12.500đ và giá vốn 18.000đ còn 19.500đ mỗi hộp; mở thêm kênh đặt trước qua nhóm Zalo của từng toà nhà (không mất hoa hồng) cho khách quen. Kênh: giao theo toà nhà, gom đơn mỗi 15 phút. Thông điệp: bỏ ảnh mâm cơm gia đình, thay bằng đồng hồ đếm 30 phút và ảnh người giao đứng ở sảnh toà văn phòng.',
  takeaway:'Mỗi P phải trả lời được: phục vụ tệp nào, giữ lời hứa nào — không trả lời được là chuỗi đang rò.',
  apply:'Cho định vị "đồ ăn vặt ít đường cho dân văn phòng ăn xế chiều". Hiện tại: gói 500g giá 180.000đ, bán ở chợ đầu mối, quảng cáo bằng hình ảnh trẻ em. Viết bảng 4 dòng (P – hiện tại – đề xuất – lý do gắn với tệp). Đạt khi: (1) mỗi đề xuất nhắc tới dân văn phòng hoặc bữa xế; (2) có ít nhất một thay đổi về quy cách gói; (3) không P nào giữ nguyên mà thiếu lý do.',
  mistakes:['Viết định vị mới nhưng giữ nguyên sản phẩm, giá, kênh cũ.','Đặt giá theo cảm tính mà không trừ chi phí của kênh hợp với tệp đã chọn.'],
  q:[
  { type:'mcq', stem:'Đoán trước: P nào đang phá lời hứa "30 phút" mạnh nhất?',
    options:[{k:'a',t:'Sản phẩm: 40 món nấu theo yêu cầu làm bếp chậm'},{k:'b',t:'Giá: 50.000đ cao hơn cơm bình dân vỉa hè gần đó'},
             {k:'c',t:'Kênh: bán qua app nên khách không gặp được chủ tiệm'},{k:'d',t:'Thông điệp: fanpage đăng quá ít bài trong một tuần'}],
    answer:'a', why:{a:'Đúng. Nấu theo yêu cầu 40 món là nguyên nhân trực tiếp khiến đơn trễ.',
      b:'Giá có thể cần xem lại, nhưng không làm đơn giao chậm.',
      c:'Gặp chủ tiệm không phải điều tệp này cần; họ cần cơm tới đúng giờ.',
      d:'Số bài đăng không ảnh hưởng tới tốc độ bếp.'} },
  { type:'mcq', stem:'Bạn chọn sửa gì đầu tiên trong thực đơn?',
    options:[{k:'a',t:'Thêm 10 món mới để khách văn phòng có thêm nhiều lựa chọn'},{k:'b',t:'Giữ 40 món nhưng tăng giá lên 60.000đ để bù thời gian chờ'},
             {k:'c',t:'Giữ nguyên thực đơn, chỉ thuê thêm người giao chạy nhanh hơn'},{k:'d',t:'Cắt còn 8 món nấu sẵn theo khung giờ để giao kịp 30 phút'}],
    answer:'d', why:{a:'Thêm món làm bếp chậm hơn, đi ngược lời hứa.',
      b:'Tệp này cần nhanh; trả thêm tiền để chờ lâu là ngược với điều họ mua.',
      c:'Chỗ nghẽn ở bếp; người giao nhanh mấy cũng phải chờ cơm.',
      d:'Đúng. Sản phẩm được thiết kế lại quanh lời hứa và quanh tệp đã chọn.'} },
  { type:'calc', stem:'Hộp cơm giá 50.000đ bán qua app, hoa hồng 25% tính trên giá bán, giá vốn món 18.000đ. Lãi gộp mỗi hộp sau hoa hồng là bao nhiêu đồng?',
    unit:'đ', ans:19500, tol:1, wrong:[[32000,'QUEN_CHI_PHI_BIEN_DOI'],[37500,'QUEN_CHI_PHI_BIEN_DOI'],[27500,'SAI_MAU_SO']], errors:['QUEN_CHI_PHI_BIEN_DOI','SAI_MAU_SO'],
    steps:['Hoa hồng = 50.000 × 25% = 12.500đ (tính trên giá bán, không phải trên giá vốn).','Lãi gộp = 50.000 − 12.500 − 18.000 = <b>19.500đ</b> mỗi hộp, khoảng 39% giá bán.'] },
  { type:'mcq', stem:'Hình ảnh và lời nói nào khớp chuỗi STP của tiệm?',
    options:[{k:'a',t:'Ảnh mâm cơm gia đình ấm cúng, kèm chữ "cơm như mẹ nấu"'},{k:'b',t:'Bảng 40 món với giá từng món, kèm chữ "đa dạng lựa chọn"'},
             {k:'c',t:'Đồng hồ đếm 30 phút và người giao ở sảnh toà văn phòng'},{k:'d',t:'Ảnh đầu bếp nổi tiếng, kèm chữ "hương vị nhà hàng sang"'}],
    answer:'c', why:{a:'Mâm cơm gia đình nói với một tệp và một dịp khác.',
      b:'"Đa dạng" đi ngược thực đơn gọn đã chọn để giữ tốc độ.',
      c:'Đúng. Hình ảnh nói đúng điểm khác biệt (30 phút) với đúng người (dân văn phòng).',
      d:'Nhà hàng sang là một khung tham chiếu khác, không phải điều tệp này cần lúc trưa.'} },
  { type:'mcq', stem:'Tình huống mới: hãng sữa chua uống định vị "bữa phụ mang tới trường cho học sinh tiểu học", nhưng chỉ bán chai 1 lít ở siêu thị sỉ, giá theo thùng. P nào lệch rõ nhất?',
    options:[{k:'a',t:'Thông điệp, vì chưa có người nổi tiếng làm gương mặt đại diện'},{k:'b',t:'Sản phẩm và kênh: chai 1 lít bán sỉ không hợp bữa phụ ở trường'},
             {k:'c',t:'Giá, vì giá theo thùng làm khách tưởng hàng kém chất lượng'},{k:'d',t:'Không lệch, vì phụ huynh mua thùng về rồi chia cho con mang đi'}],
    answer:'b', why:{a:'Người nổi tiếng không sửa được việc chai quá to để mang tới lớp.',
      b:'Đúng. Bữa phụ ở trường cần chai nhỏ, dễ cầm, bán ở nơi phụ huynh ghé hằng ngày.',
      c:'Không có dữ kiện cho thấy khách nghĩ hàng kém; vấn đề là quy cách.',
      d:'Bắt phụ huynh tự chia chai là đẩy việc của sản phẩm sang khách.'} },
  { type:'mcq', stem:'Vì sao giá cũng là hệ quả của định vị, không chỉ của chi phí?',
    options:[{k:'a',t:'Vì giá do nhà nước quy định riêng theo từng nhóm ngành hàng ăn uống'},{k:'b',t:'Vì giá thấp nhất khu vực thường thắng, bất kể định vị là gì'},
             {k:'c',t:'Vì giá báo hiệu mình đứng đâu so với lựa chọn tệp đó đang dùng'},{k:'d',t:'Vì giá nên cộng một tỉ lệ cố định vào giá vốn cho dễ quản lý'}],
    answer:'c', why:{a:'Phần lớn hàng ăn uống không bị nhà nước định giá.',
      b:'Tệp văn phòng trả cho tốc độ; rẻ nhất chưa chắc thắng.',
      c:'Đúng. Giá đặt cạnh cơm vỉa hè hay cơm nhà hàng sẽ nói tiệm đứng ở đâu trong đầu khách.',
      d:'Cộng tỉ lệ cố định bỏ qua cả định vị lẫn chi phí kênh như hoa hồng app.'} },
  { type:'mcq', stem:'Kênh app tính hoa hồng 25% nhưng mang tới nhiều khách mới; kênh Zalo toà nhà không mất hoa hồng nhưng chỉ có khách quen. Cách dùng hai kênh nào hợp với chuỗi STP?',
    options:[{k:'a',t:'App để có khách mới trong tệp, Zalo để giữ khách quen với lãi cao hơn'},{k:'b',t:'Bỏ app ngay vì hoa hồng 25% quá cao, chỉ giữ lại nhóm Zalo toà nhà'},
             {k:'c',t:'Bỏ nhóm Zalo vì quá nhỏ, dồn hết khách vào app cho dễ quản lý và đo đếm'},{k:'d',t:'Đẩy cả hai kênh sang khách gia đình để tăng giá trị mỗi đơn hàng'}],
    answer:'a', why:{a:'Đúng. Đây là đánh đổi giữa độ phủ và biên lãi; mỗi kênh làm một việc cho cùng một tệp.',
      b:'Bỏ app là mất nguồn khách mới trong tệp; Zalo chỉ nuôi được người đã biết tiệm.',
      c:'Dồn hết vào app là trả 12.500đ hoa hồng cho cả khách quen.',
      d:'Đổi sang khách gia đình là bẻ gãy tệp đã chọn.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kh11-08', skill:'comm', read:'7 phút', t:'Chọn tệp một đằng, quảng cáo nói một nẻo — tìm điểm đứt trong chuỗi STP thế nào?',
  situation:'Một thương hiệu yến mạch ăn liền ở TP.HCM chọn tệp "người đi làm cần bữa sáng nhanh, ít đường". Nhưng agency lại chạy video TikTok "ăn vặt healthy" cho sinh viên 18–22. Sau một tháng tốn 60 triệu, có 300 khách mới; khảo sát lúc giao hàng cho thấy chỉ 90 người là dân đi làm mua để ăn sáng (số minh hoạ). Báo cáo ghi: "chi phí mỗi khách 200.000đ — rất tốt".',
  concept:{ name:'Kiểm tra chuỗi STP: các mắt xích phải nói về cùng một nhóm',
    body:'Chuỗi STP đứt khi hai bước liền nhau nói về hai nhóm khác nhau. Có bốn chỗ hay đứt. (1) <b>S → T</b>: chọn một nhóm không có trong bảng phân khúc, như "người trẻ năng động". (2) <b>T → P</b>: vế "cho ai" của câu định vị khác tệp đã chọn. (3) <b>P → 4P</b>: sản phẩm, giá, kênh không giữ lời hứa (xem lại B:tp01-08). (4) <b>P → quảng cáo</b>: brief cho agency đổi tệp mà không ai để ý. Cách kiểm: viết tệp đã chọn lên đầu trang, đặt dưới nó vế "cho ai", mô tả tệp trong brief quảng cáo, và nhóm khách mới thực tế. Bốn dòng phải nói về cùng một nhóm; dòng nào khác là chỗ đứt.' },
  example:'Đặt bốn dòng cạnh nhau. Tệp đã chọn: người đi làm cần bữa sáng nhanh. Câu định vị: khớp. Brief agency: "sinh viên thích ăn vặt healthy" — đứt ở đây. Khách mới thực tế: 90 trên 300, tức 30% thuộc tệp. Tính lại: 60 triệu ÷ 90 ≈ 667.000đ cho mỗi khách đúng tệp, gấp hơn 3 lần con số 200.000đ trên báo cáo. 210 khách còn lại không vô giá trị, nhưng họ mua cho dịp khác (ăn vặt) mà hãng chưa chuẩn bị gói và giá cho dịp đó. Cách sửa: viết lại brief, chạy vào khung 6h–8h sáng, đo tỉ lệ khách đúng tệp mỗi tuần.',
  takeaway:'Đặt tệp đã chọn, câu định vị, brief quảng cáo và khách mới thực tế cạnh nhau: dòng nào lệch nhóm là chỗ đứt.',
  apply:'Cho chuỗi của một tiệm bánh: tệp đã chọn "dân văn phòng đặt bánh sinh nhật cho đồng nghiệp"; câu định vị "bánh sinh nhật giao tận văn phòng trước 15h"; brief quảng cáo nhắm "mẹ bỉm tổ chức sinh nhật cho con"; tháng qua chi 50 triệu, có 250 đơn mới, 100 đơn từ văn phòng. Viết bảng 4 dòng và chỉ ra điểm đứt. Đạt khi: (1) chỉ đúng điểm đứt ở brief quảng cáo; (2) tính đúng chi phí mỗi đơn đúng tệp là 500.000đ; (3) đề xuất một sửa đổi cụ thể cho brief.',
  mistakes:['Đọc chi phí mỗi khách trên tổng khách mới, không tách bao nhiêu người thuộc tệp đã chọn.','Duyệt brief agency mà không đặt nó cạnh tệp và câu định vị đã chốt.'],
  q:[
  { type:'mcq', stem:'Đoán trước: chuỗi STP của hãng yến mạch đứt ở mắt xích nào?',
    options:[{k:'a',t:'S → T: hãng chưa chia thị trường trước khi chọn tệp'},{k:'b',t:'T → P: câu định vị nói cho một nhóm khác tệp đã chọn'},
             {k:'c',t:'P → quảng cáo: brief cho agency đổi sang sinh viên ăn vặt'},{k:'d',t:'Không đứt: 300 khách mới, 200.000đ mỗi khách là tốt'}],
    answer:'c', why:{a:'Tệp "người đi làm cần bữa sáng nhanh" là một nhóm nhu cầu rõ; bước S → T ổn.',
      b:'Câu định vị khớp với tệp đã chọn; chỗ lệch nằm ở bước sau.',
      c:'Đúng. Tệp và định vị nói về người đi làm, quảng cáo lại nói với sinh viên.',
      d:'Con số 200.000đ tính trên cả khách ngoài tệp, nên trông rẻ hơn thực tế.'} },
  { type:'mcq', stem:'Tháng sau vẫn còn 60 triệu. Bạn làm gì trước?',
    options:[{k:'a',t:'Giữ nguyên chiến dịch vì 200.000đ mỗi khách thấp hơn mức hãng đặt ra'},{k:'b',t:'Viết lại brief theo tệp đã chọn, chạy khung sáng, đo tỉ lệ khách đúng tệp'},
             {k:'c',t:'Đổi tệp đã chọn sang sinh viên, vì quảng cáo đang kéo được nhóm này'},{k:'d',t:'Tăng gấp đôi ngân sách để có thêm khách đi làm lẫn trong số khách mới'}],
    answer:'b', why:{a:'So mức đặt ra bằng một con số tính sai mẫu số thì kết luận cũng sai theo.',
      b:'Đúng. Nối lại mắt xích đứt và đổi chỉ số đo sang khách đúng tệp.',
      c:'Đổi tệp vì quảng cáo đã lỡ chạy sai là để agency quyết định chiến lược thay mình.',
      d:'Gấp đôi tiền thì gấp đôi cả phần 70% chạy cho nhóm ngoài tệp.'} },
  { type:'calc', stem:'Chi 60 triệu, có 300 khách mới, nhưng chỉ 90 người thuộc tệp đã chọn. Chi phí cho mỗi khách mới đúng tệp là bao nhiêu đồng?',
    unit:'đ', ans:666667, tol:1000, wrong:[[200000,'SAI_MAU_SO'],[285714,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Kết quả của mục tiêu là khách thuộc tệp: 90 người.','60.000.000 ÷ 90 ≈ <b>666.667đ</b> mỗi khách đúng tệp — gấp khoảng 3,3 lần con số 200.000đ chia cho cả 300 khách.'] },
  { type:'mcq', stem:'210 khách ngoài tệp không phải "khách vô ích". Vậy vì sao họ vẫn là dấu hiệu chuỗi đang đứt?',
    options:[{k:'a',t:'Họ mua cho một dịp khác mà hãng chưa chuẩn bị sản phẩm, giá cho dịp đó'},{k:'b',t:'Vì sinh viên ít tiền nên gần như sẽ không mua lại lần thứ hai'},
             {k:'c',t:'Vì khách ngoài tệp làm hỏng số liệu nên phải xoá khỏi hệ thống'},{k:'d',t:'Vì khách ngoài tệp làm chi phí giao hàng tăng lên gấp đôi'}],
    answer:'a', why:{a:'Đúng. Ngân sách đã kéo về một nhóm mà sản phẩm, gói, giá chưa được thiết kế cho họ.',
      b:'Đó là khuôn mẫu về sinh viên; không có dữ liệu mua lại để kết luận.',
      c:'Không cần xoá khách; cần tách họ ra khi đánh giá mục tiêu.',
      d:'Không có dữ kiện về chi phí giao; vấn đề nằm ở chỗ chuỗi STP lệch.'} },
  { type:'mcq', stem:'Tình huống mới: một spa chọn tệp "phụ nữ đi làm cần thư giãn sau 19h", câu định vị khớp, nhưng spa đóng cửa lúc 18h. Chuỗi đứt ở mắt xích nào?',
    options:[{k:'a',t:'S → T, vì phụ nữ đi làm không phải một phân khúc đo được'},{k:'b',t:'P → 4P, vì giờ mở cửa không giữ lời hứa cho tệp đã chọn'},
             {k:'c',t:'T → P, vì câu định vị nói cho một nhóm khác tệp đã chọn'},{k:'d',t:'P → quảng cáo, vì quảng cáo chưa đủ đẹp để kéo khách tới'}],
    answer:'b', why:{a:'Nhóm này đo và với tới được; bước chọn tệp không có vấn đề.',
      b:'Đúng. Giờ phục vụ thuộc kênh (nơi và lúc khách nhận dịch vụ); nó phá lời hứa "sau 19h".',
      c:'Đề bài nói câu định vị khớp với tệp.',
      d:'Quảng cáo đẹp hơn chỉ đưa thêm người tới một cánh cửa đã đóng.'} },
  { type:'mcq', stem:'Cách nào phát hiện điểm đứt sớm nhất, trước khi tốn tiền chạy quảng cáo?',
    options:[{k:'a',t:'Chờ báo cáo cuối tháng rồi so doanh thu với tháng trước'},{k:'b',t:'Đếm số lượt thích video sau ba ngày chạy quảng cáo'},
             {k:'c',t:'Hỏi agency xem họ có hài lòng với ý tưởng sáng tạo không'},{k:'d',t:'Đặt tệp, câu định vị và brief cạnh nhau trước khi duyệt'}],
    answer:'d', why:{a:'Đến cuối tháng thì tiền đã tiêu; và so trước/sau không cho biết khách có thuộc tệp không.',
      b:'Lượt thích có thể đến từ bất kỳ ai; không nói gì về tệp.',
      c:'Agency hài lòng với ý tưởng không có nghĩa ý tưởng nói đúng tệp.',
      d:'Đúng. Một trang đối chiếu trước khi duyệt rẻ hơn nhiều so với đọc báo cáo sau khi chạy.'} },
  { type:'mcq', stem:'Báo cáo viết: "Sau chiến dịch, doanh số tăng 40% so với tháng trước, vậy chuỗi STP đã ổn." Lập luận này có vấn đề gì?',
    options:[{k:'a',t:'Không có vấn đề; doanh số tăng là bằng chứng chuỗi STP đã đúng'},{k:'b',t:'Mức 40% còn thấp, phải tăng gấp đôi trở lên mới chứng minh được hiệu quả'},
             {k:'c',t:'Nên so với cùng kỳ năm trước thay vì tháng trước thì sẽ kết luận được'},{k:'d',t:'So trước/sau không tách được nguyên nhân, cũng không cho biết khách có đúng tệp'}],
    answer:'d', why:{a:'Doanh số có thể tăng nhờ mùa vụ hay khách ngoài tệp; nó không kiểm được từng mắt xích.',
      b:'Mức tăng lớn hay nhỏ không trả lời được câu hỏi đúng tệp hay không.',
      c:'Đổi mốc so vẫn là so trước/sau không đối chứng, và vẫn không tách theo tệp.',
      d:'Đúng. Cần đo tỉ lệ khách mới thuộc tệp, và nếu muốn nói nhân quả thì cần nhóm đối chứng.'} }
  ] }

] });
